import type { MetadataRoute } from "next";
import { BRAND } from "@/lib/brand";

/**
 * Web app manifest: installable from Chrome and Safari. Every icon is a real file in /public generated by
 * `npm run icons` and declared at its true size; the maskable pair keeps the markhor inside Android's safe zone.
 * Installable, not offline: there is no service worker, by choice (a stale price list is worse than none).
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    id: "/",
    name: `${BRAND.name} — Vacuum Flasks & Thermos Jugs`,
    short_name: BRAND.name,
    description: BRAND.description,
    lang: "en-PK",
    dir: "ltr",
    start_url: "/?source=pwa",
    scope: "/",
    display: "standalone",
    orientation: "portrait-primary",
    background_color: "#0b0a09",
    theme_color: "#0b0a09",
    categories: ["shopping", "lifestyle", "food"],
    icons: [
      { src: "/android-icon-48x48.png", sizes: "48x48", type: "image/png", purpose: "any" },
      { src: "/android-icon-72x72.png", sizes: "72x72", type: "image/png", purpose: "any" },
      { src: "/android-icon-96x96.png", sizes: "96x96", type: "image/png", purpose: "any" },
      { src: "/android-icon-144x144.png", sizes: "144x144", type: "image/png", purpose: "any" },
      { src: "/android-icon-192x192.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/android-icon-512x512.png", sizes: "512x512", type: "image/png", purpose: "any" },
      { src: "/maskable-icon-192x192.png", sizes: "192x192", type: "image/png", purpose: "maskable" },
      { src: "/maskable-icon-512x512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
    ],
    shortcuts: [
      { name: "Vacuum jugs", url: "/vacuum-jugs", icons: [{ src: "/android-icon-96x96.png", sizes: "96x96" }] },
      { name: "Insulated bottles", url: "/insulated-bottles", icons: [{ src: "/android-icon-96x96.png", sizes: "96x96" }] },
      { name: "Your basket", url: "/cart", icons: [{ src: "/android-icon-96x96.png", sizes: "96x96" }] },
    ],
  };
}
